mapper.select:
SELECT sp.id AS sourceProductId, sp.source_product_name AS sourceProductName, sp.source_product_code AS sourceProductCode, sp.head_img_url AS headImgUrl, sp.category_name AS categoryName, COALESCE(SUM(CASE WHEN icl.change_amount < 0 THEN -icl.change_amount ELSE 0 END), 0) AS sold, COALESCE(SUM(CASE WHEN icl.change_amount > 0 THEN icl.change_amount ELSE 0 END), 0) AS restocked, COALESCE(SUM(-icl.change_amount), 0) AS netChange, COUNT(*) AS changeCount, MAX(icl.create_time) AS lastChangeTime FROM inventory_change_log icl JOIN source_product sp ON sp.id = icl.source_product_id WHERE sp.is_deleted = 0
AND icl.create_time >= #{beginTime}
AND icl.create_time <= #{endTime}
GROUP BY sp.id, sp.source_product_name, sp.source_product_code, sp.head_img_url, sp.category_name ORDER BY sold DESC
